// Git 前端公共工具: 路径转换与状态着色。

import type { GitFileStatus } from '../commands/git';

/** 绝对路径 -> 仓库相对路径 (正斜杠)。 */
export function absToRel(projectPath: string, abs: string): string {
  const base = projectPath.replace(/[\\/]+$/, '').replace(/\\/g, '/');
  const p = abs.replace(/\\/g, '/');
  return p.startsWith(`${base}/`) ? p.slice(base.length + 1) : p;
}

/** 仓库相对路径 -> 绝对路径。 */
export function relToAbs(projectPath: string, rel: string): string {
  return `${projectPath.replace(/[\\/]+$/, '')}\\${rel.replace(/\//g, '\\')}`;
}

/** 更改类型对应的 CSS 修饰类名 (用于着色)。 */
export const STATUS_CLASS: Record<string, string> = {
  M: 'git-M',
  A: 'git-A',
  U: 'git-U',
  R: 'git-R',
  D: 'git-D',
  T: 'git-T',
};

/** 更改类型短标签 (用于徽标)。 */
export const STATUS_LABEL: Record<string, string> = {
  M: 'M',
  A: 'A',
  U: 'U',
  R: 'R',
  D: 'D',
  T: 'T',
};

/** 由状态列表构建「相对路径 -> 状态」查找表。 */
export function statusMap(files: GitFileStatus[]): Map<string, GitFileStatus> {
  const map = new Map<string, GitFileStatus>();
  for (const f of files) map.set(f.path, f);
  return map;
}
